import {createWorldArt} from './world-art.js';
import {installReferencePlayer} from './reference-player.js';
import {run,THREE,box,sphere,floor,ring,makeHero,replaceHero,poseHero} from './lib/core.js';
import {Platformer} from './rules.js';
run({title:'Super Mario 65',models:{luigi:'models/luigi.glb'},genre:'Mario fan game / 2.5D platformer',accent:'#f6cf75',background:0x99ccde,description:'Choose Mario or Luigi, explore a little 3D world map, then step into side-scrolling stages. Collect coins, cross moving platforms and unlock the next world.',controls:[['A / D','Move'],['Space','Jump · hold higher'],['E','Bridge switch'],['M','World map'],['P / Esc','Pause']],touch:[['KeyA','←'],['KeyD','→'],['Space','Jump'],['KeyE','Switch'],['KeyM','Map']],options:[{id:'character',label:'Character',values:[['mario','Mario'],['luigi','Luigi']]},{id:'assist',label:'Challenge',values:[['no','Standard · five lives'],['yes','Relaxed · hazards disabled']]}],buildIntro:'A small Mario fan platformer with 3D characters and scenery, movement constrained to a 2D gameplay plane, and a selectable 3D world map.',build:[['Characters in Blender','Built Mario and Luigi fan models with hats, overalls, moustaches, gloves and boots. Added named deformation bones, packed UVs and baked colour/normal/ORM maps.'],['2.5D stages','The player moves and jumps along a side-view plane while Three.js renders depth, lighting, character animation, scenery and coins.'],['New scenery and shading','Original multi-part mushrooms, hollow-rimmed pipes, petal flowers, bevelled star models, castle towers, waving flags and softer character material highlights enrich the scene.'],['World-map flow','Three themed islands unlock in order. Completing a stage returns to the map; browser-local progression remembers your unlocked worlds.'],['Platform mechanics','Coins, springs, moving bridges, a bridge switch, checkpoints, hazards, lives and an assist mode form the route through three short stages.']]},(ctx,model)=>{
const {scene,camera,stage}=ctx,map=new THREE.Group(),levelScene=new THREE.Group();scene.add(map,levelScene);const hero=makeHero(model,scene,.65),water=floor(map,180,0x60b7c7);water.position.y=-1;const nodeMeshes=[],coins=[],platforms=[],ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let sim=new Platformer(),level=1,mapMode=true,options={},unlocked=1,selected=1,finished=false;const names=['Meadow Trail','Sunset Switches','Castle Carnival'];
function cylinder(group,x,y,z,r,h,color){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,24),new THREE.MeshStandardMaterial({color,roughness:.8}));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;group.add(m);return m}
function roof(group,x,y,z,r,color){const m=new THREE.Mesh(new THREE.ConeGeometry(r,r*1.3,12),new THREE.MeshStandardMaterial({color}));m.position.set(x,y,z);m.castShadow=true;group.add(m)}
for(let i=0;i<3;i++){const x=i*12;cylinder(map,x,-.5,0,4.4,1.2,0xe6d9a7);cylinder(map,x,.15,0,4.1,.4,i===1?0xa6b96f:0x74b86a);if(i<2)box(map,x+6,.05,0,5,.14,1.2,0xd4b77a);const node=cylinder(map,x,.46,0,.85,.16,0xe6bf63);node.userData.world=i+1;nodeMeshes.push(node);for(const [dx,dz]of [[-2,-2],[2,-2],[-2,2]]){cylinder(map,x+dx,.85,dz,.12,1.3,0x897449);const canopy=sphere(map,x+dx,1.7,dz,.72,0x4c9a59);canopy.scale.y=1.25}if(i===0){box(map,x,1.1,-2.3,1.4,1.7,1.1,0xf2d69b);roof(map,x,2.4,-2.3,1.1,0xd96d6c)}if(i===1){for(let j=0;j<3;j++)box(map,x+(j-1)*.9,1+j*.4,-2, .65,1+j*.8,.65,0xceb176)}if(i===2){box(map,x,1.2,-2,2.3,2,1.2,0xe2d9be);for(const dx of [-1.2,1.2]){cylinder(map,x+dx,1.6,-2,.48,2.8,0xded7c5);roof(map,x+dx,3.3,-2,.65,0xd16a7a)}box(map,x,2.6,-2,.8,.8,.9,0xe8d9bc);roof(map,x,3.5,-2,.65,0xd16a7a)}}
for(let i=0;i<12;i++){const cloud=sphere(map,(i%4)*13-8,6+(i%3),Math.floor(i/4)*13-15,1.1,0xe4eef0);cloud.scale.set(2.4,.55,.8);cloud.castShadow=false}
const art=createWorldArt();art.map(map);art.styleHero(hero);installReferencePlayer(ctx);
const overlay=document.createElement('section');overlay.className='mario-world-map';overlay.hidden=true;document.body.append(overlay);const mapButton=document.createElement('button');mapButton.textContent='World map';mapButton.className='mario-map-button';mapButton.onclick=()=>showMap();document.querySelector('.game-header nav').insertBefore(mapButton,document.getElementById('pause-button'));
function showMap(){mapMode=true;map.visible=true;levelScene.visible=false;hero.visible=true;selected=Math.min(unlocked,3);overlay.hidden=false;overlay.innerHTML=`<p>SUPER MARIO 65 / WORLD SELECT</p><h2>A little adventure awaits.</h2><div>${names.map((n,i)=>`<button data-world="${i+1}" ${i+1>unlocked?'disabled':''}><b>${i+1>unlocked?'🔒':i+1}</b><span>${n}<small>${i+1>unlocked?'Complete the previous world':i+1<unlocked?'Completed · replay':'Ready to explore'}</small></span><em>→</em></button>`).join('')}</div><small>Click an island or choose a world below. Progress saves in this browser.</small>`;nodeMeshes.forEach((m,i)=>m.material.color.set(i+1<=unlocked?0xf6d076:0x777e7c));ctx.keys.clear();ctx.pressed.clear()}
function buildLevel(){art.clearLevel();levelScene.traverse(o=>{if(o.isMesh)o.geometry.dispose()});levelScene.clear();coins.length=platforms.length=0;const palettes=[{ground:0x74ab5b,earth:0xb58e5d,sky:0xa5d4e2},{ground:0xc4ad65,earth:0xa47964,sky:0xd8b3a0},{ground:0x929cc5,earth:0x5b627d,sky:0x434b73}],palette=palettes[level-1];scene.background.set(palette.sky);scene.fog.color.set(palette.sky);for(const p of sim.platforms){const m=box(levelScene,p.x,p.y-.38,0,p.w,.75,3,palette.earth);platforms.push(m);box(levelScene,p.x,p.y+.01,0,p.w,.08,3.02,palette.ground);if(p.spring)ring(levelScene,p.x,p.y+.08,0,.6,0xffd47d)}for(const t of sim.tokens){const m=new THREE.Mesh(new THREE.TorusGeometry(.23,.075,8,20),new THREE.MeshStandardMaterial({color:0xf6c754,metalness:.55,roughness:.25}));m.position.set(t.x,t.y,0);m.castShadow=true;levelScene.add(m);coins.push(m)}const hz=level===1?0:level===2?2.2:2.1+(level-1)*.12,hx=level===1?6:level===2?17:35;const enemy=sphere(levelScene,hx,hz+.35,0,.35,0x8a6040);enemy.scale.y=.9;for(const dx of [-.15,.15]){sphere(levelScene,hx+dx,hz+.4,.29,.08,0xf1e9d5);sphere(levelScene,hx+dx,hz+.4,.35,.035,0x292623);box(levelScene,hx+dx,hz+.04,.03,.25,.1,.3,0x57452d)}for(const x of [4,16,29,40]){const hill=sphere(levelScene,x,1.5,-8,4,level===3?0x6b7197:0x65a477);hill.scale.set(1.3,1,.45)}for(const x of [8,26,38]){cylinder(levelScene,x,.7,3.2,.65,1.4,0x548e59);cylinder(levelScene,x,1.45,3.2,.78,.18,0x6fa96b)}for(const x of [11,21,34]){box(levelScene,x,4.8,-.1,.75,.75,.75,0xe5b95f);box(levelScene,x,4.8,.29,.4,.07,.02,0xffe9ae)}cylinder(levelScene,47,3,0,.04,3,0xd4decb);const flag=box(levelScene,47.48,4.25,0,.9,.5,.04,0xed6962);for(const x of [18,30]){cylinder(levelScene,x,1,5.5,.4,2,0xf0dfc1);roof(levelScene,x,2.3,5.5,.75,0xe87b7b)}
const scenery=new THREE.Group();scenery.name='level-art';levelScene.add(scenery);art.level(scenery,level);
const front=floor(levelScene,140,level===3?0x27384e:0x6aa9ba);front.position.y=-8;}
function enter(n){if(n>unlocked)return;level=n;sim=new Platformer({assist:options.assist});sim.level=n;sim.loadLevel();finished=false;mapMode=false;overlay.hidden=true;map.visible=false;levelScene.visible=true;hero.visible=true;buildLevel();camera.position.set(3,4.5,15);camera.lookAt(3,1.5,0);ctx.announce(names[n-1]+' · collect 5 coins');stage.focus()}
overlay.onclick=e=>{const b=e.target.closest('[data-world]');if(b)enter(Number(b.dataset.world))};stage.addEventListener('pointerdown',e=>{if(!mapMode||!ctx.playing)return;const r=stage.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-((e.clientY-r.top)/r.height)*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(nodeMeshes,false)[0];if(hit)enter(hit.object.userData.world)});
return {reset(o){options=o;unlocked=1;try{unlocked=Math.max(1,Math.min(3,Number(localStorage.getItem('po-mario-worlds'))||1))}catch{}replaceHero(hero,o.character==='luigi'?ctx.models.luigi:model,.65);art.styleHero(hero);showMap();scene.background.set(0x99ccde);scene.fog.color.set(0x99ccde)},update(dt){art.update(ctx.time);if(ctx.pressed.has('KeyM')){showMap();return}if(mapMode){camera.position.lerp(new THREE.Vector3(13,22,24),1-Math.exp(-dt*3));camera.lookAt(12,0,0);hero.position.set((selected-1)*12,.45,.2);hero.rotation.y=.2;poseHero(hero,ctx.time,0);ctx.hud(`<div><strong>WORLD MAP</strong><small>${unlocked} / 3 WORLDS UNLOCKED · ${options.character==='luigi'?'LUIGI':'MARIO'}</small></div>`);return}sim.update(dt,ctx.keys,ctx.pressed);if(sim.level!==level||sim.over&&sim.won){unlocked=Math.min(3,Math.max(unlocked,level+1));try{localStorage.setItem('po-mario-worlds',String(unlocked))}catch{}if(level===3){if(!finished){finished=true;ctx.end('A star-worthy adventure.',`All three worlds cleared. ${sim.total} coins collected. Your worlds remain unlocked for another visit.`)}}else{showMap();ctx.announce('World cleared! The next island is open.')}return}const p=sim.player;hero.position.set(p.x,p.y,0);if(Math.abs(p.vx)>.2)hero.rotation.y=p.vx>0?Math.PI/2:-Math.PI/2;poseHero(hero,ctx.time,Math.abs(p.vx)/6);platforms[3].position.x=sim.platforms[3].x;coins.forEach((m,i)=>{m.visible=!sim.tokens[i].got;m.position.x=sim.tokens[i].x;m.rotation.y+=dt*2});const cx=Math.max(3,Math.min(44,p.x+2));camera.position.lerp(new THREE.Vector3(cx,Math.max(4,p.y+2.7),15),1-Math.exp(-dt*4));camera.lookAt(cx,Math.max(1.7,p.y+1),0);ctx.hud(`<div><strong>${options.character==='luigi'?'LUIGI':'MARIO'} · WORLD ${level}</strong><small>${names[level-1].toUpperCase()}</small></div><div><strong>COINS ${sim.found} / 5</strong><small>${options.assist==='yes'?'RELAXED MODE':sim.lives+' LIVES'} · M: MAP</small></div>`);for(const event of sim.events){if(event==='token')ctx.tone(600+sim.found*45,.08);if(event==='checkpoint')ctx.announce('Checkpoint reached.');if(event==='locked')ctx.announce('Collect five coins to reach the flag.');if(event==='hurt')ctx.announce('Back to your checkpoint.');if(event==='bridge')ctx.announce(sim.bridgeStopped?'Bridge stopped.':'Bridge moving.')}if(sim.over&&!finished){finished=true;ctx.end('Let’s give that another go.','Try Relaxed mode, or return to the world map to replay an unlocked stage.')}},snapshot(){return {map:mapMode,level,unlocked,coins:sim.found,lives:sim.lives,player:sim.player}}};
});
